namespace Canopy.Desktop;
public static class App
{
    [STAThread] public static int Main(string[] args)
    {
        var app=new Application();
        if(args.Length>0 && args[0]=="--smoke-test") { var w=new MainWindow(); w.LoadAudit(MainWindow.Sample); if(w.ResourceCount!=6||!w.ResultsSelected||!w.ConnectionFieldsEmpty) return 1; File.WriteAllText(args[1],"Desktop startup, blank connection fields, snapshot import and automatic Results navigation passed."); return 0; }
        var window=new MainWindow();
        if(args.Length==2 && args[0]=="--audit-smoke")window.Loaded+=async(_,_)=>{try{Directory.CreateDirectory(args[1]);await window.RunAudit();window.SaveSmoke(args[1]);app.Shutdown(window.ResourceCount>0?0:1);}catch{app.Shutdown(1);}};
        if(args.Length==3 && args[0]=="--preview-smoke")window.Loaded+=async(_,_)=>{try{window.LoadAudit(File.ReadAllText(args[1]));await Task.Delay(500);window.SaveSmoke(args[2]);app.Shutdown(0);}catch{app.Shutdown(1);}};
        if(args.Length==2 && (args[0]=="--audit-preview"||args[0]=="--audit-preview-light"||args[0]=="--wait-preview"))window.Loaded+=async(_,_)=>{window.LoadAudit(MainWindow.Sample);window.ShowPage("Audit");if(args[0]=="--wait-preview")window.PreviewWait();if(args[0]=="--audit-preview-light")window.SetAppearance("Light");await Task.Delay(500);window.SaveSmoke(args[1]);app.Shutdown(0);};
        if(args.Length==2&&args[0]=="--dependency-preview")window.Loaded+=(_,_)=>window.PreviewDependency(args[1]);
        app.Run(window);return 0;
    }
}
