    public void LoadAudit(string json)
    {
        if(json.Length>100*1024*1024)throw new InvalidDataException("Snapshot exceeds 100 MB.");
        var next=JsonNode.Parse(json) as JsonObject??throw new InvalidDataException("Invalid JSON object.");
        if(S(next,"schemaVersion")!="0.2-delegated")throw new InvalidDataException("Expected a 0.2-delegated snapshot.");
        foreach(var key in new[]{"resources","grants","sharePointGroups","directoryGroups","coverage"})if(next[key] is not JsonArray a||a.Count>250000)throw new InvalidDataException("Invalid collection: "+key);
        var ids=new HashSet<string>();foreach(var r in (JsonArray)next["resources"]!)if(r is not JsonObject||!ids.Add(S(r,"id"))||S(r,"id")=="")throw new InvalidDataException("Invalid resource IDs.");
        foreach(var r in (JsonArray)next["resources"]!){if(r!["hasUniqueRoleAssignments"] is not null && (r["hasUniqueRoleAssignments"] is not JsonValue v||!v.TryGetValue<bool>(out _)))throw new InvalidDataException("Invalid inheritance flag.");}
        foreach(var g in (JsonArray)next["grants"]!){if(g is not JsonObject||g["principal"] is not JsonObject||g["roles"] is not JsonArray roles||roles.Any(r=>r is not JsonObject))throw new InvalidDataException("Invalid grant.");}
        foreach(var key in new[]{"sharePointGroups","directoryGroups"})foreach(var g in (JsonArray)next[key]!){if(g is not JsonObject||g["members"] is not JsonArray ms||ms.Count>50000||ms.Any(m=>m is not JsonObject))throw new InvalidDataException("Invalid membership collection.");}
        if(((JsonArray)next["coverage"]!).Any(c=>c is not JsonObject))throw new InvalidDataException("Invalid coverage record.");
        audit=next;selected=null;RenderTree();coverage.Text=string.Join("\n\n",Array("coverage").Select(c=>S(c,"operation")+" · "+S(c,"state")+"\n"+S(c,"reason")));
        status.Text=$"{ResourceCount} resources · {Array("resources").Count(r=>S(r,"type")=="file")} files · {Array("grants").Count} grants · {(S(next,"state")=="completed"?"Collection completed for selected scope":"Collection has gaps — review Coverage")} · {S(next,"completedAt")}";if(Array("resources").FirstOrDefault() is JsonObject first)ShowResource(first);
        resultsSummary.Text=S(next["scope"],"siteUrl")+" · "+S(next["scope"],"library")+"\n"+status.Text;reportSummary.Text=resultsSummary.Text;foreach(var export in exportButtons)export.IsEnabled=true;ShowPage("Results");
    }
    void Import(){var d=new OpenFileDialog{Filter="Canopy audit (*.json)|*.json"};if(d.ShowDialog()==true)try{LoadAudit(File.ReadAllText(d.FileName));}catch(Exception e){MessageBox.Show(e.Message,"Import failed");}}
    void Export(string format){if(audit==null){MessageBox.Show("Run or import an audit first.");return;}var d=new SaveFileDialog{Filter=$"{format.ToUpperInvariant()} report|*.{format}",FileName="365Canopy-audit."+format};if(d.ShowDialog()==true)try{string text=format switch{"html"=>AuditReport.Html(audit),"csv"=>AuditReport.Csv(audit),_=>audit.ToJsonString(new(){WriteIndented=true})};File.WriteAllText(d.FileName,text,new System.Text.UTF8Encoding(format=="csv"));}catch(Exception e){MessageBox.Show(e.Message,"Export failed");}}
    void RenderTree()
    {
        tree.Items.Clear();var nodes=new Dictionary<string,TreeViewItem>();var resources=Array("resources").OfType<JsonObject>().ToList();var resourceMap=resources.ToDictionary(r=>S(r,"id"));
        foreach(var r in resources){var n=new TreeViewItem{Header=S(r,"title")+(r["hasUniqueRoleAssignments"]==null?" · unknown":B(r,"hasUniqueRoleAssignments")?" · unique":""),Tag=r,IsExpanded=resources.Count<500||S(r,"type") is "web" or "library",ToolTip=S(r,"url")};nodes[S(r,"id")]=n;}
        foreach(var r in resources){string parent=S(r,"parentResourceId");if(parent==""&&S(r,"type")=="library")parent=S(resources.FirstOrDefault(x=>S(x,"type")=="web"),"id");if(parent==""&&S(r,"type")=="folder")parent=S(resources.FirstOrDefault(x=>S(x,"type")=="library"),"id");var n=nodes[S(r,"id")];if(search.Text!=""){if((S(r,"url")+S(r,"title")).Contains(search.Text,StringComparison.OrdinalIgnoreCase))tree.Items.Add(n);}else if(parent!=S(r,"id")&&nodes.TryGetValue(parent,out var p)&&!WouldCycle(r,resourceMap))p.Items.Add(n);else tree.Items.Add(n);}
    }
    static bool WouldCycle(JsonObject r,Dictionary<string,JsonObject> nodes){var seen=new HashSet<string>{S(r,"id")};var parent=S(r,"parentResourceId");while(parent!=""){if(!seen.Add(parent))return true;parent=nodes.TryGetValue(parent,out var node)?S(node,"parentResourceId"):"";}return false;}
    void ShowResource(JsonObject r){selected=r;resourceTitle.Text=S(r,"title");var source=S(r,"sourceResourceId");var sourceNode=Array("resources").FirstOrDefault(n=>S(n,"id")==source);resourceNote.Text=S(r,"url")+"\n"+(r["hasUniqueRoleAssignments"]==null?"Permission inheritance unknown":B(r,"hasUniqueRoleAssignments")?"Unique permissions":"Inherited permissions")+"\nPermission source: "+(sourceNode==null?"Unresolved":S(sourceNode,"title"));grants.Children.Clear();members.Children.Clear();var found=Array("grants").OfType<JsonObject>().Where(g=>S(g,"resourceId")==source).ToList();foreach(var g in found){var p=g["principal"]!;var roles=string.Join(", ",((JsonArray)g["roles"]!).Select(x=>S(x,"name")));grants.Children.Add(Button(S(p,"title")+" · "+roles,()=>ShowPrincipal((JsonObject)p)));}if(found.Count==0){grants.Children.Add(Text("No grants recorded. Review coverage; this does not prove no access."));members.Children.Add(Text("People",20));members.Children.Add(Muted("Select a recorded grant to explore its membership. No grants were recorded for this permission source."));}else ShowPrincipal((JsonObject)found[0]["principal"]!);}
    void ShowPrincipal(JsonObject p){members.Children.Clear();members.Children.Add(Text("Access path",12));members.Children.Add(Text(S(p,"title"),20));members.Children.Add(Text("Observed memberships; policies may affect access.",12));AppendPrincipal(members,p,new HashSet<string>());}
    void AppendPrincipal(StackPanel panel,JsonNode p,HashSet<string> seen)
    {
        if(seen.Count>=200){panel.Children.Add(Text("Expansion depth limit reached."));return;}
        if(S(p,"type")=="SharePointGroup"){if(!seen.Add("sp:"+S(p,"id"))){panel.Children.Add(Text("Cycle · group already shown"));return;}var g=Array("sharePointGroups").FirstOrDefault(g=>S(g,"id")==S(p,"id"));panel.Children.Add(Text("Classic SharePoint group · "+S(g,"state")));if(g?["members"] is JsonArray ms)foreach(var m in ms){if(m==null)continue;var child=new StackPanel{Margin=new Thickness(14,0,0,0)};panel.Children.Add(child);child.Children.Add(Text(S(m,"title")));AppendPrincipal(child,m,new(seen));}else panel.Children.Add(Text("Members not collected."));return;}
        var match=System.Text.RegularExpressions.Regex.Match(S(p,"loginName"),@"^c:(?:0t\.c\|tenant\||0o\.c\|federateddirectoryclaimprovider\|)([\da-f-]{36})(_o)?$",System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        if(match.Success){AppendDirectory(panel,match.Groups[1].Value,match.Groups[2].Success?"owners":"members",seen);return;}panel.Children.Add(Text(S(p,"loginName") is {Length:>0} login?login:S(p,"id"),12));
    }
    void AppendDirectory(StackPanel panel,string id,string relationship,HashSet<string> seen){string key=id+":"+relationship;if(!seen.Add(key)){panel.Children.Add(Text("Cycle · group already shown"));return;}var g=Array("directoryGroups").FirstOrDefault(g=>S(g,"id").Equals(id,StringComparison.OrdinalIgnoreCase)&&(S(g,"relationship")==""?"members":S(g,"relationship"))==relationship);panel.Children.Add(Text((S(g,"displayName")==""?id:S(g,"displayName"))+" · "+relationship));if(g==null){panel.Children.Add(Text("Not collected · people unknown"));return;}panel.Children.Add(Text(S(g,"state")+" · "+S(g,"reason"),11));if(g["members"] is JsonArray ms){if(ms.Count==0)panel.Children.Add(Text(S(g,"state")=="observed"?"No entries returned":"People unknown"));foreach(var m in ms){if(m==null)continue;var child=new StackPanel{Margin=new Thickness(14,0,0,0)};panel.Children.Add(child);if(S(m,"type")=="#microsoft.graph.group")AppendDirectory(child,S(m,"id"),"members",new(seen));else child.Children.Add(Text((S(m,"displayName")==""?S(m,"id"):S(m,"displayName"))+"\n"+(S(m,"userPrincipalName")==""?"Identity details unavailable":S(m,"userPrincipalName"))+"\nObject ID: "+S(m,"id"),12));}}
    }
    public void SaveSmoke(string directory){Directory.CreateDirectory(directory);if(audit==null)throw new InvalidOperationException("No audit loaded.");File.WriteAllText(Path.Combine(directory,"audit.json"),audit.ToJsonString(new(){WriteIndented=true}));UpdateLayout();var bmp=new RenderTargetBitmap((int)ActualWidth,(int)ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(this);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using var stream=File.Create(Path.Combine(directory,"desktop.png"));encoder.Save(stream);File.WriteAllText(Path.Combine(directory,"result.txt"),status.Text);}
    void SetWaitAnimation(bool active){windTree.Visibility=active?Visibility.Visible:Visibility.Collapsed;var transform=(RotateTransform)windTree.RenderTransform;transform.BeginAnimation(RotateTransform.AngleProperty,null);if(active&&SystemParameters.ClientAreaAnimation)transform.BeginAnimation(RotateTransform.AngleProperty,new DoubleAnimation(-4,4,TimeSpan.FromSeconds(1.5)){AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever,EasingFunction=new SineEase{EasingMode=EasingMode.EaseInOut}});}
    public void PreviewWait(){SetWaitAnimation(true);run.IsEnabled=false;status.Text="Animation preview only - no tenant connection or audit.";}
    public async Task RunAudit()
    {
        if(busy)return;if(!DependencyReady){await SetupDependency();if(!DependencyReady)return;}try{new SiteProfile("Current site",site.Text,tenant.Text,client.Text,library.Text,files.IsChecked==true,recursive.IsChecked==true).Validate();}catch(InvalidDataException e){MessageBox.Show(e.Message,"Check site details");return;}
        string home=AppContext.BaseDirectory;string ps=Path.Combine(home,"runtime","powershell","pwsh.exe"),script=Path.Combine(home,"src","Canopy.Checkpoint","Desktop-Audit.ps1");if(!File.Exists(ps)||!File.Exists(script)){MessageBox.Show("Use the complete packaged build; the bundled collector/runtime is missing.");return;}
        busy=true;connectionForm.IsEnabled=false;files.IsEnabled=false;recursive.IsEnabled=false;run.IsEnabled=false;cancel.IsEnabled=true;status.Text="Microsoft sign-in / read-only collection in progress…";SetWaitAnimation(true);
        try{var start=new ProcessStartInfo(ps){WorkingDirectory=home,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"-NoLogo","-NoProfile","-File",script,"-SiteUrl",site.Text.Trim(),"-TenantId",tenant.Text.Trim(),"-ClientId",client.Text.Trim(),"-LibraryName",library.Text.Trim(),"-PnPModulePath",Path.Combine(DependencyHome,"PnP.PowerShell.psd1")})start.ArgumentList.Add(arg);if(recursive.IsChecked==true)start.ArgumentList.Add("-RecursiveFolders");if(files.IsChecked==true)start.ArgumentList.Add("-IncludeFiles");start.Environment["POWERSHELL_TELEMETRY_OPTOUT"]="1";start.Environment["POWERSHELL_UPDATECHECK"]="Off";process=Process.Start(start)!;var output=ReadCollectorOutput(process.StandardOutput);var error=process.StandardError.ReadToEndAsync();await process.WaitForExitAsync();var line=await output;await error;if(process.ExitCode!=0||line==null)throw new InvalidOperationException("Collection interrupted or failed. No previous snapshot was replaced. Check prerequisites and complete Microsoft sign-in.");var payload=JsonNode.Parse(line[7..]);if(payload?["state"]?.ToString()=="failed"||(payload?["resources"] as JsonArray)?.Count==0)throw new InvalidOperationException("No resources were collected. Check Microsoft sign-in and site access; previous results were retained.");LoadAudit(line[7..]);}
        catch(Exception e){status.Text=e.Message;}finally{process?.Dispose();process=null;busy=false;connectionForm.IsEnabled=true;files.IsEnabled=true;recursive.IsEnabled=files.IsChecked!=true;run.IsEnabled=true;cancel.IsEnabled=false;SetWaitAnimation(false);}
    }
    Window CreateDependencyDialog()
    {
        var dialog=new Window{Title="One-time audit setup",Owner=this,Width=620,Height=520,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize};
        var content=new StackPanel{Margin=new Thickness(24)};dialog.Content=new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};dialog.SetResourceReference(BackgroundProperty,"PageBrush");dialog.SetResourceReference(ForegroundProperty,"InkBrush");
        content.Children.Add(Text("Download the SharePoint audit dependency",22));
        content.Children.Add(Text("365Canopy downloads PnP.PowerShell 3.4.1 directly from PowerShell Gallery and verifies the reviewed archive hash. It is stored on this Windows account and reused for future audits. Internet access is needed for this setup. No tenant connection is made."));
        content.Children.Add(Text("The download includes Microsoft components with separate license terms. Review these before continuing:",12));
        foreach(var link in new[]{("PowerShell Gallery package and licenses","https://www.powershellgallery.com/packages/PnP.PowerShell/3.4.1"),("MSAL NativeInterop terms","https://www.nuget.org/packages/Microsoft.Identity.Client.NativeInterop/0.20.6/License"),("SharePoint client component terms","https://github.com/SharePoint/sp-dev-docs/blob/main/assets/MicrosoftSharePointClientComponentsEULA.docx")})content.Children.Add(Button(link.Item1,()=>Process.Start(new ProcessStartInfo(link.Item2){UseShellExecute=true})));
        content.Children.Add(Button("Download and set up",()=>{dialog.DialogResult=true;}));
        return dialog;
    }
    public void PreviewDependency(string directory)
    {
        var dialog=CreateDependencyDialog();dialog.Loaded+=async(_,_)=>{await Task.Delay(500);Directory.CreateDirectory(directory);dialog.UpdateLayout();var bmp=new RenderTargetBitmap((int)dialog.ActualWidth,(int)dialog.ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(dialog);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using(var stream=File.Create(Path.Combine(directory,"setup.png")))encoder.Save(stream);dialog.Close();Application.Current.Shutdown();};dialog.ShowDialog();
    }
    async Task SetupDependency()
    {
        if(busy)return;
        var dialog=CreateDependencyDialog();
        if(dialog.ShowDialog()!=true)return;
        string home=AppContext.BaseDirectory,ps=Path.Combine(home,"runtime","powershell","pwsh.exe"),script=Path.Combine(home,"src","Canopy.Checkpoint","Setup-Dependency.ps1");
        busy=true;setup.IsEnabled=false;run.IsEnabled=false;cancel.IsEnabled=true;SetWaitAnimation(true);status.Text="Downloading and verifying the audit dependency…";
        try{var start=new ProcessStartInfo(ps){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"-NoLogo","-NoProfile","-File",script,"-Destination",DependencyHome})start.ArgumentList.Add(arg);start.Environment["POWERSHELL_TELEMETRY_OPTOUT"]="1";start.Environment["POWERSHELL_UPDATECHECK"]="Off";process=Process.Start(start)!;var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();await process.WaitForExitAsync();var result=await output;await error;if(process.ExitCode!=0||!result.Contains("CANOPY_SETUP:ready")||!DependencyReady)throw new InvalidOperationException("Setup did not complete. Check your internet connection and retry; existing dependencies were preserved.");setup.Visibility=Visibility.Collapsed;status.Text="Audit dependency ready. Enter your site details and run an administrator audit.";}
        catch(Exception e){status.Text=e.Message;}finally{process?.Dispose();process=null;busy=false;setup.IsEnabled=true;run.IsEnabled=true;cancel.IsEnabled=false;SetWaitAnimation(false);}
    }
    async Task<string?> ReadCollectorOutput(StreamReader reader)
    {
        string? snapshot=null;
        while(await reader.ReadLineAsync() is {} line) {
            if(line.StartsWith("CANOPY_PROGRESS:"))status.Text=line[16..];
            else if(line.StartsWith("CANOPY:"))snapshot=line;
        }
        return snapshot;
    }
